18	package org.apache.kafka.metadata;
19	
20	import org.apache.kafka.common.DirectoryId;
21	import org.apache.kafka.common.Endpoint;
22	import org.apache.kafka.common.Node;
23	import org.apache.kafka.common.Uuid;
24	import org.apache.kafka.common.metadata.RegisterBrokerRecord;
25	import org.apache.kafka.common.metadata.RegisterBrokerRecord.BrokerEndpoint;
26	import org.apache.kafka.common.metadata.RegisterBrokerRecord.BrokerFeature;
27	import org.apache.kafka.common.security.auth.SecurityProtocol;
28	import org.apache.kafka.image.writer.ImageWriterOptions;
29	import org.apache.kafka.server.common.ApiMessageAndVersion;
30	
31	import java.util.ArrayList;
32	import java.util.Collections;
33	import java.util.HashMap;
34	import java.util.List;
35	import java.util.Map;
36	import java.util.Map.Entry;
37	import java.util.Objects;
38	import java.util.Optional;
39	import java.util.stream.Collectors;
40	
41	/**
42	 * An immutable class which represents broker registrations.
43	 */
44	public class BrokerRegistration {
45	    public static class Builder {
46	        private int id;
47	        private long epoch;
48	        private Uuid incarnationId;
49	        private Map<String, Endpoint> listeners;
50	        private Map<String, VersionRange> supportedFeatures;
51	        private Optional<String> rack;
52	        private boolean fenced;
53	        private boolean inControlledShutdown;
54	        private boolean isMigratingZkBroker;
55	        private List<Uuid> directories;
56	
57	        public Builder() {
58	            this.id = 0;
59	            this.epoch = -1;
60	            this.incarnationId = null;
61	            this.listeners = new HashMap<>();
62	            this.supportedFeatures = new HashMap<>();
63	            this.rack = Optional.empty();
64	            this.fenced = false;
65	            this.inControlledShutdown = false;
66	            this.isMigratingZkBroker = false;
67	            this.directories = List.of();
68	        }
69	
70	        public Builder setId(int id) {
71	            this.id = id;
72	            return this;
73	        }
74	
75	        public Builder setEpoch(long epoch) {
76	            this.epoch = epoch;
77	            return this;
78	        }
79	
80	        public Builder setIncarnationId(Uuid incarnationId) {
81	            this.incarnationId = incarnationId;
82	            return this;
83	        }
84	
85	        public Builder setListeners(List<Endpoint> listeners) {
86	            Map<String, Endpoint> listenersMap = new HashMap<>();
87	            for (Endpoint endpoint : listeners) {
88	                listenersMap.put(endpoint.listener(), endpoint);
89	            }
90	            this.listeners = listenersMap;
91	            return this;
92	        }
93	
94	        public Builder setListeners(Map<String, Endpoint> listeners) {
95	            this.listeners = listeners;
96	            return this;
97	        }
98	
99	        public Builder setSupportedFeatures(Map<String, VersionRange> supportedFeatures) {
100	            this.supportedFeatures = supportedFeatures;
101	            return this;
102	        }
103	
104	        public Builder setRack(Optional<String> rack) {
105	            Objects.requireNonNull(rack);
106	            this.rack = rack;
107	            return this;
108	        }
109	
110	        public Builder setFenced(boolean fenced) {
111	            this.fenced = fenced;
112	            return this;
113	        }
114	
115	        public Builder setInControlledShutdown(boolean inControlledShutdown) {
116	            this.inControlledShutdown = inControlledShutdown;
117	            return this;
118	        }
119	
120	        public Builder setIsMigratingZkBroker(boolean isMigratingZkBroker) {
121	            this.isMigratingZkBroker = isMigratingZkBroker;
122	            return this;
123	        }
124	
125	        public Builder setDirectories(List<Uuid> directories) {
126	            this.directories = directories;
127	            return this;
128	        }
129	
130	        public BrokerRegistration build() {
131	            return new BrokerRegistration(
132	                id,
133	                epoch,
134	                incarnationId,
135	                listeners,
136	                supportedFeatures,
137	                rack,
138	                fenced,
139	                inControlledShutdown,
140	                isMigratingZkBroker,
141	                directories);
142	        }
143	    }
144	
145	    private final int id;
146	    private final long epoch;
147	    private final Uuid incarnationId;
148	    private final Map<String, Endpoint> listeners;
149	    private final Map<String, VersionRange> supportedFeatures;
150	    private final Optional<String> rack;
151	    private final boolean fenced;
152	    private final boolean inControlledShutdown;
153	    private final boolean isMigratingZkBroker;
154	    private final List<Uuid> directories;
155	
156	    private BrokerRegistration(
157	        int id,
158	        long epoch,
159	        Uuid incarnationId,
160	        Map<String, Endpoint> listeners,
161	        Map<String, VersionRange> supportedFeatures,
162	        Optional<String> rack,
163	        boolean fenced,
164	        boolean inControlledShutdown,
165	        boolean isMigratingZkBroker,
166	        List<Uuid> directories
167	    ) {
168	        this.id = id;
169	        this.epoch = epoch;
170	        this.incarnationId = incarnationId;
171	        Map<String, Endpoint> newListeners = new HashMap<>(listeners.size());
172	        for (Entry<String, Endpoint> entry : listeners.entrySet()) {
173	            if (entry.getValue().listener().isEmpty()) {
174	                throw new IllegalArgumentException("Broker listeners must be named.");
175	            }
176	            newListeners.put(entry.getKey(), entry.getValue());
177	        }
178	        this.listeners = Collections.unmodifiableMap(newListeners);
179	        Objects.requireNonNull(supportedFeatures);
180	        this.supportedFeatures = new HashMap<>(supportedFeatures);
181	        this.rack = rack;
182	        this.fenced = fenced;
183	        this.inControlledShutdown = inControlledShutdown;
184	        this.isMigratingZkBroker = isMigratingZkBroker;
185	        directories = new ArrayList<>(directories);
186	        directories.sort(Uuid::compareTo);
187	        this.directories = Collections.unmodifiableList(directories);
188	    }
189	
190	    public static BrokerRegistration fromRecord(RegisterBrokerRecord record) {
191	        Map<String, Endpoint> listeners = new HashMap<>();
192	        for (BrokerEndpoint endpoint : record.endPoints()) {
193	            listeners.put(endpoint.name(), new Endpoint(endpoint.name(),
194	                SecurityProtocol.forId(endpoint.securityProtocol()),
195	                endpoint.host(),
196	                endpoint.port()));
197	        }
198	        Map<String, VersionRange> supportedFeatures = new HashMap<>();
199	        for (BrokerFeature feature : record.features()) {
200	            supportedFeatures.put(feature.name(), VersionRange.of(
201	                feature.minSupportedVersion(), feature.maxSupportedVersion()));
202	        }
203	        return new BrokerRegistration(record.brokerId(),
204	            record.brokerEpoch(),
205	            record.incarnationId(),
206	            listeners,
207	            supportedFeatures,
208	            Optional.ofNullable(record.rack()),
209	            record.fenced(),
210	            record.inControlledShutdown(),
211	            record.isMigratingZkBroker(),
212	            record.logDirs());
213	    }
214	
215	    public int id() {
216	        return id;
217	    }
218	
219	    public long epoch() {
220	        return epoch;
221	    }
222	
223	    public Uuid incarnationId() {
224	        return incarnationId;
225	    }
226	
227	    public Map<String, Endpoint> listeners() {
228	        return listeners;
229	    }
230	
231	    public Optional<Node> node(String listenerName) {
232	        Endpoint endpoint = listeners().get(listenerName);
233	        if (endpoint == null) {
234	            return Optional.empty();
235	        }
236	        return Optional.of(new Node(id, endpoint.host(), endpoint.port(), rack.orElse(null), fenced));
237	    }
238	    
239	    public List<Node> nodes() {
240	        return listeners.keySet().stream().flatMap(l -> node(l).stream()).toList();
241	    }
242	
243	    public Map<String, VersionRange> supportedFeatures() {
244	        return supportedFeatures;
245	    }
246	
247	    public Optional<String> rack() {
248	        return rack;
249	    }
250	
251	    public boolean fenced() {
252	        return fenced;
253	    }
254	
255	    public boolean inControlledShutdown() {
256	        return inControlledShutdown;
257	    }
258	
259	    public List<Uuid> directories() {
260	        return directories;
261	    }
262	
263	    public boolean hasOnlineDir(Uuid dir) {
264	        return DirectoryId.isOnline(dir, directories);
265	    }
266	
267	    public List<Uuid> directoryIntersection(List<Uuid> otherDirectories) {
268	        List<Uuid> results = new ArrayList<>();
269	        for (Uuid directory : directories) {
270	            if (otherDirectories.contains(directory)) {
271	                results.add(directory);
272	            }
273	        }
274	        return results;
275	    }
276	
277	    public List<Uuid> directoryDifference(List<Uuid> otherDirectories) {
278	        List<Uuid> results = new ArrayList<>();
279	        for (Uuid directory : directories) {
280	            if (!otherDirectories.contains(directory)) {
281	                results.add(directory);
282	            }
283	        }
284	        return results;
285	    }
286	
287	    public ApiMessageAndVersion toRecord(ImageWriterOptions options) {
288	        RegisterBrokerRecord registrationRecord = new RegisterBrokerRecord().
289	            setBrokerId(id).
290	            setRack(rack.orElse(null)).
291	            setBrokerEpoch(epoch).
292	            setIncarnationId(incarnationId).
293	            setFenced(fenced).
294	            setInControlledShutdown(inControlledShutdown);
295	
296	        if (isMigratingZkBroker) {
297	            if (options.metadataVersion().isMigrationSupported()) {
298	                registrationRecord.setIsMigratingZkBroker(isMigratingZkBroker);
299	            } else {
300	                options.handleLoss("the isMigratingZkBroker state of one or more brokers");
301	            }
302	        }
303	
304	        if (directories.isEmpty() || options.metadataVersion().isDirectoryAssignmentSupported()) {
305	            registrationRecord.setLogDirs(directories);
306	        } else {
307	            options.handleLoss("the online log directories of one or more brokers");
308	        }
309	
310	        for (Entry<String, Endpoint> entry : listeners.entrySet()) {
311	            Endpoint endpoint = entry.getValue();
312	            registrationRecord.endPoints().add(new BrokerEndpoint().
313	                setName(entry.getKey()).
314	                setHost(endpoint.host()).
315	                setPort(endpoint.port()).
316	                setSecurityProtocol(endpoint.securityProtocol().id));
317	        }
318	
319	        for (Entry<String, VersionRange> entry : supportedFeatures.entrySet()) {
320	            registrationRecord.features().add(new BrokerFeature().
321	                setName(entry.getKey()).
322	                setMinSupportedVersion(entry.getValue().min()).
323	                setMaxSupportedVersion(entry.getValue().max()));
324	        }
325	
326	        return new ApiMessageAndVersion(registrationRecord,
327	            options.metadataVersion().registerBrokerRecordVersion());
328	    }
329	
330	    @Override
331	    public int hashCode() {
332	        return Objects.hash(id, epoch, incarnationId, listeners, supportedFeatures,
333	            rack, fenced, inControlledShutdown, isMigratingZkBroker, directories);
334	    }
335	
336	    @Override
337	    public boolean equals(Object o) {
338	        if (!(o instanceof BrokerRegistration other)) return false;
339	        return other.id == id &&
340	            other.epoch == epoch &&
341	            other.incarnationId.equals(incarnationId) &&
342	            other.listeners.equals(listeners) &&
343	            other.supportedFeatures.equals(supportedFeatures) &&
344	            other.rack.equals(rack) &&
345	            other.fenced == fenced &&
346	            other.inControlledShutdown == inControlledShutdown &&
347	            other.isMigratingZkBroker == isMigratingZkBroker &&
348	            other.directories.equals(directories);
349	    }
350	
351	    @Override
352	    public String toString() {
353	        return "BrokerRegistration(id=" + id +
354	                ", epoch=" + epoch +
355	                ", incarnationId=" + incarnationId +
356	                ", listeners=[" +
357	                listeners.keySet().stream().sorted().
358	                        map(n -> listeners.get(n).toString()).
359	                        collect(Collectors.joining(", ")) +
360	                "], supportedFeatures={" +
361	                supportedFeatures.keySet().stream().sorted().
362	                        map(k -> k + ": " + supportedFeatures.get(k)).
363	                        collect(Collectors.joining(", ")) +
364	                "}" +
365	                ", rack=" + rack +
366	                ", fenced=" + fenced +
367	                ", inControlledShutdown=" + inControlledShutdown +
368	                ", isMigratingZkBroker=" + isMigratingZkBroker +
369	                ", directories=" + directories +
370	                ")";
371	    }
372	
373	    public BrokerRegistration cloneWith(
374	        Optional<Boolean> fencingChange,
375	        Optional<Boolean> inControlledShutdownChange,
376	        Optional<List<Uuid>> directoriesChange
377	    ) {
378	        boolean newFenced = fencingChange.orElse(fenced);
379	        boolean newInControlledShutdownChange = inControlledShutdownChange.orElse(inControlledShutdown);
380	        List<Uuid> newDirectories = directoriesChange.orElse(directories);
381	
382	        if (newFenced == fenced && newInControlledShutdownChange == inControlledShutdown && newDirectories.equals(directories))
383	            return this;
384	
385	        return new BrokerRegistration(
386	            id,
387	            epoch,
388	            incarnationId,
389	            listeners,
390	            supportedFeatures,
391	            rack,
392	            newFenced,
393	            newInControlledShutdownChange,
394	            isMigratingZkBroker,
395	            newDirectories
396	        );
397	    }
398	}
